"""Product analytics dashboard: conversion statistics over customer sessions."""


def conversion_rate(events):
    """The conversion rate of a list of sessions. See SPEC.md section 1."""
    if not events:
        return 0.0
    hits = sum(1 for e in events if e["converted"] is True)
    return hits / len(events)


def pooled_conversion_rate(groups):
    """The pooled conversion rate across groups of sessions. See SPEC.md section 2."""
    total = sum(len(events) for events in groups.values())
    if not total:
        return 0.0
    hits = sum(1 for events in groups.values() for e in events if e["converted"] is True)
    return hits / total


def conversions_in_window(daily_counts, days):
    """Sum over a trailing window of daily counts. See SPEC.md section 3."""
    if days == 0:
        return 0
    return sum(daily_counts[-days:])


def conversion_rate_by_group(groups):
    """The conversion rate of each group. See SPEC.md section 9."""
    return {name: conversion_rate(groups[name]) if groups[name] else None
            for name in sorted(groups)}


def longest_conversion_streak(daily_counts):
    """Longest run of days with converted sessions. See SPEC.md section 10."""
    best = cur = 0
    for c in daily_counts:
        if c > 0:
            cur += 1
            best = max(best, cur)
        else:
            cur = 0
    return best

"""Product analytics dashboard: conversion statistics over customer sessions."""


def parse_session_log(lines):
    """Parse log lines into sessions. See SPEC.md section 4."""
    out = []
    flags = {"1": True, "0": False, "": None}
    for line_number, line in enumerate(lines, 1):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        fields = [field.strip() for field in line.split(",")]
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected three fields")
        id_, day, flag = fields
        try:
            day = int(day)
        except ValueError as exc:
            raise ValueError(f"line {line_number}: invalid day") from exc
        if flag not in flags:
            raise ValueError(f"line {line_number}: invalid converted value")
        out.append({"id": id_, "day": day, "converted": flags[flag]})
    return out


def dedupe_sessions(events):
    """Remove duplicate sessions. See SPEC.md section 5."""
    seen = {}
    for e in events:
        seen[e["id"]] = e
    return sorted(seen.values(), key=lambda e: (e["day"], e["id"]))


def daily_conversion_counts(events, start_day, end_day):
    """Daily counts of converted sessions. See SPEC.md section 6."""
    counts = [0] * max(0, end_day - start_day + 1)
    for e in events:
        if start_day <= e["day"] <= end_day and e["converted"] is True:
            counts[e["day"] - start_day] += 1
    return counts

import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_none_counts_as_not_converted():
    assert conversion_rate([{"converted": True}, {"converted": None},
                            {"converted": False}]) == 1 / 3
    assert conversion_rate([{"converted": None}]) == 0.0
    assert conversion_rate([]) == 0.0


def test_pooled_conversion_rate_weights_sessions_not_groups():
    groups = {"a": [{"converted": True}],
              "b": [{"converted": False}, {"converted": None}, {"converted": False}],
              "empty": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({}) == 0.0
    assert pooled_conversion_rate({"empty": []}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 3), (2, 5), (3, 6), (10, 6)])
def test_conversions_in_window(days, expected):
    assert conversions_in_window([1, 2, 3], days) == expected
    assert conversions_in_window([], days) == 0


def test_parse_session_log_whitespace_comments_and_flags():
    lines = ["\n", "  # comment,with,commas", "  a  ,  -2 , 1  ",
             "b, 3, 0", " c , 4,  ", "   "]
    assert parse_session_log(lines) == [
        {"id": "a", "day": -2, "converted": True},
        {"id": "b", "day": 3, "converted": False},
        {"id": "c", "day": 4, "converted": None},
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,extra", "a,no,1", "a,1,yes"])
def test_parse_session_log_reports_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 3\b"):
        parse_session_log([" # comment", " ", bad_line])


def test_dedupe_sessions_keeps_last_duplicate_and_sorts_by_day_then_id():
    events = [
        {"id": "z", "day": 1, "converted": True},
        {"id": "b", "day": 2, "converted": False},
        {"id": "a", "day": 2, "converted": True},
        {"id": "z", "day": 2, "converted": None},
    ]
    assert dedupe_sessions(events) == [events[2], events[1], events[3]]
    assert dedupe_sessions([]) == []


def test_daily_conversion_counts_inclusive_with_gaps_and_outside():
    events = [
        {"day": 0, "converted": True},
        {"day": 1, "converted": True},
        {"day": 1, "converted": True},
        {"day": 2, "converted": None},
        {"day": 3, "converted": False},
        {"day": 4, "converted": True},
    ]
    assert daily_conversion_counts(events, 1, 3) == [2, 0, 0]
    assert daily_conversion_counts([], 1, 3) == [0, 0, 0]
    assert daily_conversion_counts(events, 3, 1) == []


def test_campaign_summary_uses_pooled_rate_calendar_days_and_nonempty_groups():
    groups = {
        "a": [{"day": 1, "converted": True}],
        "b": [{"day": 3, "converted": False}, {"day": 4, "converted": False}],
        "empty": [],
    }
    assert campaign_summary(groups, 2) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert campaign_summary(groups, 4) == {"rate": 0.333, "recent": 1, "groups": 2}
    assert campaign_summary(groups, 0)["recent"] == 0
    assert campaign_summary({"empty": []}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert campaign_summary({}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [{"converted": True}], "empty": [],
              "a": [{"converted": True}], "b": [{"converted": False}]}
    assert top_converting_groups(groups, 2) == ["a", "z"]
    assert top_converting_groups(groups, 10) == ["a", "z", "b"]
    assert top_converting_groups(groups, 0) == []


def test_conversion_rate_by_group_includes_empty_groups_in_sorted_order():
    result = conversion_rate_by_group({"z": [], "b": [{"converted": None}],
                                       "a": [{"converted": True}]})
    assert list(result.items()) == [("a", 1.0), ("b", 0.0), ("z", None)]


def test_longest_conversion_streak_resets_on_zero_and_negative():
    assert longest_conversion_streak([1, 2, 0, 1, -1, 3, 4, 5]) == 3
    assert longest_conversion_streak([0, -1, 0]) == 0
    assert longest_conversion_streak([]) == 0
